jedi.inference.gradual.annotation._infer:
def _infer_param(function_value, param):
    """
    Infers the type of a function parameter, using type annotations.
    """
    annotation = param.annotation
    if annotation is None:
        all_params = [child for child in param.parent.children if child.type == 'param']
        node = param.parent.parent
        comment = parser_utils.get_following_comment_same_line(node)
        if comment is None:
            return NO_VALUES
        match = re.match('^#\\s*type:\\s*\\(([^#]*)\\)\\s*->', comment)
        if not match:
            return NO_VALUES
        params_comments = _split_comment_param_declaration(match.group(1))
        index = all_params.index(param)
        if len(params_comments) != len(all_params):
            debug.warning('Comments length != Params length %s %s', params_comments, all_params)
        if function_value.is_bound_method():
            if index == 0:
                return NO_VALUES
            index -= 1
        if index >= len(params_comments):
            return NO_VALUES
        param_comment = params_comments[index]
        return _infer_annotation_string(function_value.get_default_param_context(), param_comment)
    context = function_value.get_default_param_context()
    return infer_annotation(context, annotation)

jedi.inference.gradual.annotation._split:
def _split_comment_param_declaration(decl_text):
    """
    Split decl_text on commas, but group generic expressions
    together.

    For example, given "foo, Bar[baz, biz]" we return
    ['foo', 'Bar[baz, biz]'].

    """
    try:
        node = parse(decl_text, error_recovery=False).children[0]
    except ParserSyntaxError:
        debug.warning('Comment annotation is not valid Python: %s' % decl_text)
        return []
    if node.type in ['name', 'atom_expr', 'power']:
        return [node.get_code().strip()]
    params = []
    try:
        children = node.children
    except AttributeError:
        return []
    else:
        for child in children:
            if child.type in ['name', 'atom_expr', 'power']:
                params.append(child.get_code().strip())
    return params

jedi.inference.gradual.annotation.infer_:
@inference_state_method_cache()
def infer_param(function_value, param, ignore_stars=False):
    values = _infer_param(function_value, param)
    if (ignore_stars or not values):
        return values
    inference_state = function_value.inference_state
    if param.star_count == 1:
        tuple_ = builtin_from_name(inference_state, 'tuple')
        return ValueSet([GenericClass(tuple_, TupleGenericManager((values, )))])
    elif param.star_count == 2:
        dct = builtin_from_name(inference_state, 'dict')
        generics = (ValueSet([builtin_from_name(inference_state, 'str')]), values)
        return ValueSet([GenericClass(dct, TupleGenericManager(generics))])
    return values

jedi.inference.compiled.subprocess.funct:
def _find_module_py33(string, path=None, loader=None, full_name=None, is_global_search=True):
    if not loader:
        spec = importlib.machinery.PathFinder.find_spec(string, path)
        if spec is not None:
            loader = spec.loader
    if (loader is None and path is None):
        try:
            spec = importlib.util.find_spec(string)
            if spec is not None:
                loader = spec.loader
        except ValueError as e:
            raise ImportError('Originally  ' + repr(e))
    if loader is None:
        raise ImportError("Couldn't find a loader for {}".format(string))
    return _from_loader(loader, string)

def _from_loader(loader, string):
    try:
        is_package_method = loader.is_package
    except AttributeError:
        is_package = False
    else:
        is_package = is_package_method(string)
    try:
        get_filename = loader.get_filename
    except AttributeError:
        return (None, is_package)
    else:
        module_path = get_filename(string)
    try:
        f = type(loader).get_source
    except AttributeError:
        raise ImportError('get_source was not defined on loader')
    if f is not importlib.machinery.SourceFileLoader.get_source:
        code = loader.get_source(string)
    else:
        code = _get_source(loader, string)
    if code is None:
        return (None, is_package)
    if isinstance(loader, zipimporter):
        return (ZipFileIO(module_path, code, Path(loader.archive)), is_package)
    return (KnownContentFileIO(module_path, code), is_package)

def _find_module(string, path=None, full_name=None, is_global_search=True):
    """
    Provides information about a module.

    This function isolates the differences in importing libraries introduced with
    python 3.3 on; it gets a module name and optionally a path. It will return a
    tuple containin an open file for the module (if not builtin), the filename
    or the name of the module if it is a builtin one and a boolean indicating
    if the module is contained in a package.
    """
    spec = None
    loader = None
    for finder in sys.meta_path:
        if (is_global_search and finder != importlib.machinery.PathFinder):
            p = None
        else:
            p = path
        try:
            find_spec = finder.find_spec
        except AttributeError:
            continue
        spec = find_spec(string, p)
        if spec is not None:
            if spec.origin == 'frozen':
                continue
            loader = spec.loader
            if (loader is None and not spec.has_location):
                full_name = (string if not path else full_name)
                implicit_ns_info = ImplicitNSInfo(full_name, spec.submodule_search_locations._path)
                return (implicit_ns_info, True)
            break
    return _find_module_py33(string, path, loader)

jedi.api.project._is_potential_project:
def _is_potential_project(path):
    for name in _CONTAINS_POTENTIAL_PROJECT:
        try:
            if path.joinpath(name).exists():
                return True
        except OSError:
            continue
    return False

jedi.api.project.get_default_project:
def get_default_project(path=None):
    """
    If a project is not defined by the user, Jedi tries to define a project by
    itself as well as possible. Jedi traverses folders until it finds one of
    the following:

    1. A ``.jedi/config.json``
    2. One of the following files: ``setup.py``, ``.git``, ``.hg``,
       ``requirements.txt`` and ``MANIFEST.in``.
    """
    if path is None:
        path = Path.cwd()
    elif isinstance(path, str):
        path = Path(path)
    check = path.absolute()
    probable_path = None
    first_no_init_file = None
    for dir in chain([check], check.parents):
        try:
            return Project.load(dir)
        except (FileNotFoundError, IsADirectoryError, PermissionError):
            pass
        except NotADirectoryError:
            continue
        if first_no_init_file is None:
            if dir.joinpath('__init__.py').exists():
                continue
            elif not dir.is_file():
                first_no_init_file = dir
        if _is_django_path(dir):
            project = Project(dir)
            project._django = True
            return project
        if (probable_path is None and _is_potential_project(dir)):
            probable_path = dir
    if probable_path is not None:
        return Project(probable_path)
    if first_no_init_file is not None:
        return Project(first_no_init_file)
    curdir = (path if path.is_dir() else path.parent)
    return Project(curdir)

jedi.api.project._is_django_path:
def _is_django_path(directory):
    """ Detects the path of the very well known Django library (if used) """
    try:
        with open(directory.joinpath('manage.py'), 'rb') as f:
            return b'DJANGO_SETTINGS_MODULE' in f.read()
    except (FileNotFoundError, IsADirectoryError, PermissionError):
        return False

parso.python.errors._remove_parens:
def _remove_parens(atom):
    """
    Returns the inner part of an expression like `(foo)`. Also removes nested
    parens.
    """
    try:
        children = atom.children
    except AttributeError:
        pass
    else:
        if (len(children) == 3 and children[0] == '('):
            return _remove_parens(atom.children[1])
    return atom

parso.python.errors._get_rhs_name:
def _get_rhs_name(node, version):
    type_ = node.type
    if type_ == 'lambdef':
        return 'lambda'
    elif type_ == 'atom':
        comprehension = _get_comprehension_type(node)
        (first, second) = node.children[:2]
        if comprehension is not None:
            return comprehension
        elif second.type == 'dictorsetmaker':
            if version < (3, 8):
                return 'literal'
            elif (second.children[1] == ':' or second.children[0] == '**'):
                if version < (3, 10):
                    return 'dict display'
                else:
                    return 'dict literal'
            else:
                return 'set display'
        elif (first == '(' and ((second == ')' or (len(node.children) == 3 and node.children[1].type == 'testlist_comp')))):
            return 'tuple'
        elif first == '(':
            return _get_rhs_name(_remove_parens(node), version=version)
        elif first == '[':
            return 'list'
        elif (first == '{' and second == '}'):
            if version < (3, 10):
                return 'dict display'
            else:
                return 'dict literal'
        elif (first == '{' and len(node.children) > 2):
            return 'set display'
    elif type_ == 'keyword':
        if 'yield' in node.value:
            return 'yield expression'
        if version < (3, 8):
            return 'keyword'
        else:
            return str(node.value)
    elif (type_ == 'operator' and node.value == '...'):
        if version < (3, 10):
            return 'Ellipsis'
        else:
            return 'ellipsis'
    elif type_ == 'comparison':
        return 'comparison'
    elif type_ in ('string', 'number', 'strings'):
        return 'literal'
    elif type_ == 'yield_expr':
        return 'yield expression'
    elif type_ == 'test':
        return 'conditional expression'
    elif type_ in ('atom_expr', 'power'):
        if node.children[0] == 'await':
            return 'await expression'
        elif node.children[-1].type == 'trailer':
            trailer = node.children[-1]
            if trailer.children[0] == '(':
                return 'function call'
            elif trailer.children[0] == '[':
                return 'subscript'
            elif trailer.children[0] == '.':
                return 'attribute'
    elif (('expr' in type_ and 'star_expr' not in type_) or '_test' in type_ or type_ in ('term', 'factor')):
        if version < (3, 10):
            return 'operator'
        else:
            return 'expression'
    elif type_ == 'star_expr':
        return 'starred'
    elif type_ == 'testlist_star_expr':
        return 'tuple'
    elif type_ == 'fstring':
        return 'f-string expression'
    return type_

parso.python.errors._get_comprehension_t:
def _get_comprehension_type(atom):
    (first, second) = atom.children[:2]
    if (second.type == 'testlist_comp' and second.children[1].type in _COMP_FOR_TYPES):
        if first == '[':
            return 'list comprehension'
        else:
            return 'generator expression'
    elif (second.type == 'dictorsetmaker' and second.children[-1].type in _COMP_FOR_TYPES):
        if second.children[1] == ':':
            return 'dict comprehension'
        else:
            return 'set comprehension'
    return None

parso.cache.clear_inactive_cache:
def clear_inactive_cache(cache_path=None, inactivity_threshold=_CACHED_FILE_MAXIMUM_SURVIVAL):
    if cache_path is None:
        cache_path = _default_cache_path
    if not cache_path.exists():
        return False
    for dirname in os.listdir(cache_path):
        version_path = cache_path.joinpath(dirname)
        if not version_path.is_dir():
            continue
        for file in os.scandir(version_path):
            if file.stat().st_atime + _CACHED_FILE_MAXIMUM_SURVIVAL <= time.time():
                try:
                    os.remove(file.path)
                except OSError:
                    continue
    else:
        return True

parso.cache._touch:
def _touch(path):
    try:
        os.utime(path, None)
    except FileNotFoundError:
        try:
            file = open(path, 'a')
            file.close()
        except (OSError, IOError):
            return False
    return True

jedi.inference.arguments.iterate_argumen:
def iterate_argument_clinic(inference_state, arguments, clinic_string):
    """Uses a list with argument clinic information (see PEP 436)."""
    clinic_args = list(_parse_argument_clinic(clinic_string))
    iterator = PushBackIterator(arguments.unpack())
    for (i, (name, optional, allow_kwargs, stars)) in enumerate(clinic_args):
        if stars == 1:
            lazy_values = []
            for (key, argument) in iterator:
                if key is not None:
                    iterator.push_back((key, argument))
                    break
                lazy_values.append(argument)
            yield ValueSet([iterable.FakeTuple(inference_state, lazy_values)])
            lazy_values
            continue
        elif stars == 2:
            raise NotImplementedError()
        (key, argument) = next(iterator, (None, None))
        if key is not None:
            debug.warning('Keyword arguments in argument clinic are currently not supported.')
            raise ParamIssue
        if (argument is None and not optional):
            debug.warning('TypeError: %s expected at least %s arguments, got %s', name, len(clinic_args), i)
            raise ParamIssue
        value_set = (NO_VALUES if argument is None else argument.infer())
        if (not value_set and not optional):
            debug.warning('argument_clinic "%s" not resolvable.', name)
            raise ParamIssue
        yield value_set
